SINA_SMART["viro1-intro"] = {"lecture":"viro1-intro","title":"Introduction to medical virology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-intro:s0","text":"Describe and explain: History","topic":"History","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"viro1-intro:e0","text":"Viruses: obligate intracellular parasites; no ribosomes, no energy system.","topic":"What a virus is","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e1","text":"Only one type of nucleic acid; assembled, not divided.","topic":"What a virus is","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e2","text":"Size does not define a virus: Mimivirus > Mycoplasma.","topic":"What a virus is","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e3","text":"Virion = genome + capsid (± envelope).","topic":"Structure","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e4","text":"Naked viruses: parvo, adeno, papilloma, picorna, HAV, HEV.","topic":"Classification","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e5","text":"Baltimore classes I-VII by genome and replication strategy.","topic":"Classification","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e6","text":"Seven steps: attachment, penetration, uncoating, replication, synthesis, assembly, release.","topic":"Infection and the life cycle","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e7","text":"Susceptibility = receptor; permissiveness = complete replication possible.","topic":"Infection and the life cycle","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e8","text":"HDV is a satellite virus needing HBV.","topic":"Infection and the life cycle","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-intro:e9","text":"Oncogenic: HPV, HBV, HCV, EBV, HHV-8, HTLV-1.","topic":"Emergence, cancer and control","sec":5,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"ikv3bt":"a","prwklg":"a","ltolr5":"a","152w8kz":"a","1y5pvc3":"a","1g3k2tm":"a","1tab02p":"a","ih0e57":"a","1klvh4p":"a","1dp5t7x":"a","1nepva":"a","6j8nte":"a","187983q":"x","qljfce":"x","wxu4wp":"x","nufypu":"x"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":4},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-intro:s0":{"s":0,"u":["Smallpox is thought to have killed Pharaoh Ramses V (1196 BCE). 'Virus' is Latin for poisonous fluid.","In the 1880s Pasteur (rabies) and Koch saw that some pathogens were invisible under the microscope."],"dp":[]},"viro1-intro:e0":{"s":1,"u":["Viruses: obligate intracellular parasites; no ribosomes, no energy system.","Viruses are submicroscopic obligate intracellular parasites : they have no energy-generating system and no ribosomes, so they cannot make proteins alone (HIV has 9 genes and uses about 200 host dependency factors)."],"dp":[]},"viro1-intro:e1":{"s":1,"u":["Only one type of nucleic acid; assembled, not divided.","What makes them unique: virions are assembled from preformed components , they do not grow or divide , they contain only one type of nucleic acid (DNA or RNA), and they carry a receptor-binding protein to dock onto cells."],"dp":[]},"viro1-intro:e2":{"s":1,"u":["Size does not define a virus: Mimivirus > Mycoplasma.","Most are 12-400 nm, but size alone does not define them: Mimivirus (400 nm) is larger than the smallest bacteria ( Mycoplasma , 200-300 nm)."],"dp":[]},"viro1-intro:e3":{"s":2,"u":["Virion = genome + capsid (± envelope).","A virion is the complete particle: the genome (DNA or RNA) inside a protein capsid made of capsomeres (together the nucleocapsid ), sometimes surrounded by a lipid envelope taken from the host cell and carrying viral glycoproteins.","The outer surface (capsid or envelope) binds the cellular receptor."],"dp":[]},"viro1-intro:e4":{"s":3,"u":["Naked viruses: parvo, adeno, papilloma, picorna, HAV, HEV.","Naked RNA viruses: picornaviruses, HAV and HEV .","Naked DNA viruses: parvovirus, adenovirus, papillomavirus (papova)."],"dp":[{"h":"Why naked viruses are harder to kill","t":"An envelope is a lipid membrane: detergents, alcohol, drying and bile destroy it, and without it the virus cannot attach. Naked viruses such as norovirus, rotavirus, HAV and poliovirus have only a protein capsid, which resists drying, acid, bile and alcohol hand gels. That is why they spread by the faeco-oral route, survive on surfaces, and why handwashing with soap and water is recommended during norovirus outbreaks."}]},"viro1-intro:e5":{"s":3,"u":["Baltimore classes I-VII by genome and replication strategy.","The Baltimore system groups viruses by genome and replication: I dsDNA, II ssDNA, III dsRNA, IV (+)ssRNA, V (−)ssRNA, VI RNA with reverse transcription (retroviruses), VII DNA with reverse transcription (HBV)."],"dp":[]},"viro1-intro:e6":{"s":4,"u":["Seven steps: attachment, penetration, uncoating, replication, synthesis, assembly, release.","The cycle has seven stages (about 6-8 hours): attachment, penetration, uncoating, genome replication, protein synthesis, assembly, release."],"dp":[]},"viro1-intro:e7":{"s":4,"u":["Susceptibility = receptor; permissiveness = complete replication possible.","Permissiveness : the cell supplies the factors for complete replication.","Susceptibility : the cell has the receptor (defines tropism)."],"dp":[]},"viro1-intro:e8":{"s":4,"u":["HDV is a satellite virus needing HBV.","Satellite viruses are defective and need a helper: hepatitis D needs HBV ; adeno-associated virus needs adenovirus."],"dp":[]},"viro1-intro:e9":{"s":5,"u":["Oncogenic: HPV, HBV, HCV, EBV, HHV-8, HTLV-1.","Oncogenic viruses : HPV (cervical cancer), HBV and HCV (hepatocellular carcinoma), EBV (Burkitt lymphoma, nasopharyngeal carcinoma), HHV-8 (Kaposi sarcoma), HTLV-1 (adult T-cell leukaemia)."],"dp":[]}},"meta":{"ikv3bt":{"a":"recall","vg":"viro1-intro:e0/recall/1"},"prwklg":{"a":"recall","vg":"viro1-intro:e1/recall/1"},"ltolr5":{"a":"recall","vg":"viro1-intro:e3/recall/1"},"152w8kz":{"a":"recall","vg":"viro1-intro:e4/recall/1"},"1y5pvc3":{"a":"recall","vg":"viro1-intro:e5/recall/1"},"1g3k2tm":{"a":"recall","vg":"viro1-intro:e5/recall/1"},"1tab02p":{"a":"recall","vg":"viro1-intro:e7/recall/1"},"ih0e57":{"a":"recall","vg":"viro1-intro:e8/recall/1"},"1klvh4p":{"a":"recall","vg":"viro1-intro:e4/recall/2"},"1dp5t7x":{"a":"recall","vg":"viro1-intro:e9/recall/1"},"1nepva":{"a":"recall","vg":"viro1-intro:e9/recall/2"},"6j8nte":{"a":"recall","vg":"viro1-intro:e1/recall/2"}},"explRev":"a213c9740a59"};
